use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Dumps an unpretty version of a tokenstream. Takes any type which implements"] # [doc = " `Display`."] # [doc = ""] # [doc = " This is mostly useful for visualizing the output of a procedural macro, as"] # [doc = " it makes it marginally more readable. It is used in the implementation of"] # [doc = " `test_derive!` to unprettily print the output."] # [doc = ""] # [doc = " # Stability"] # [doc = ""] # [doc = " The stability of the output of this function is not guaranteed. Do not"] # [doc = " assert that the output of this function does not change between minor"] # [doc = " versions."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " # use quote::quote;"] # [doc = " assert_eq!("] # [doc = "     synstructure::unpretty_print(quote! {"] # [doc = "         const _: () = {"] # [doc = "             extern crate krate;"] # [doc = "             impl<T, U> krate::Trait for A<T, U>"] # [doc = "             where"] # [doc = "                 Option<U>: krate::Trait,"] # [doc = "                 U: krate::Trait"] # [doc = "             {"] # [doc = "                 fn a() {}"] # [doc = "             }"] # [doc = "         };"] # [doc = "     }),"] # [doc = "     \"const _ : ("] # [doc = "     )"] # [doc = " = {"] # [doc = "     extern crate krate ;"] # [doc = "     impl < T , U > krate :: Trait for A < T , U > where Option < U > : krate :: Trait , U : krate :: Trait {"] # [doc = "         fn a ("] # [doc = "             )"] # [doc = "         {"] # [doc = "             }"] # [doc = "         }"] # [doc = "     }"] # [doc = " ;"] # [doc = " \""] # [doc = " )"] # [doc = " ```"] pub fn unpretty_print < T : std :: fmt :: Display > (ts : T) -> String { let mut res = String :: new () ; let raw_s = ts . to_string () ; let mut s = & raw_s [..] ; let mut indent = 0 ; while let Some (i) = s . find (& ['(' , '{' , '[' , ')' , '}' , ']' , ';'] [..]) { match & s [i ..= i] { "(" | "{" | "[" => indent += 1 , ")" | "}" | "]" => indent -= 1 , _ => { } } res . push_str (& s [..= i]) ; res . push ('\n') ; for _ in 0 .. indent { res . push_str ("    ") ; } s = trim_start_matches (& s [i + 1 ..] , ' ') ; } res . push_str (s) ; res }
}